using System.Security.Claims;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Rendering;
using Microsoft.EntityFrameworkCore;
using NorviaBackoffice.Data;
using NorviaBackoffice.Models.Entities;
using NorviaBackoffice.Models.ViewModels;
using NorviaBackoffice.Services.Interfaces;
namespace NorviaBackoffice.Controllers;
[Authorize(Policy="Administrator")]
public sealed class TenantAdminsController(NorviaDbContext db,ITenantProvisioningService provisioning,ILogger<TenantAdminsController> logger):Controller
{
    public async Task<IActionResult> Index(string? search,CancellationToken ct){var q=db.UserExtended.AsNoTracking().Include(x=>x.Tenant).Where(x=>!x.IsStudent);if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>(x.Name??"").Contains(search)||(x.Email??"").Contains(search)||x.Tenant.Name.Contains(search));ViewBag.Search=search;return View(await q.OrderBy(x=>x.Name).ToListAsync(ct));}
    [HttpGet] public async Task<IActionResult> Create(CancellationToken ct)=>View("Form",await Prepare(new TenantAdminFormViewModel(),ct));
    [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Create(TenantAdminFormViewModel model,CancellationToken ct){await Validate(model,ct,true);if(!ModelState.IsValid)return View("Form",await Prepare(model,ct));var actor=UserId();db.UserExtended.Add(new UserExtended{TenantId=model.TenantId,Name=model.Name.Trim(),Surname=model.Surname?.Trim(),Email=model.Email.Trim(),PhoneNumber=model.PhoneNumber?.Trim(),UserInternalId=model.UserInternalId?.Trim(),UserRoleId=model.UserRoleId,Address=model.Address?.Trim(),IsStudent=false,IsActive=model.IsActive,CreatedBy=actor,CreatedOn=DateTime.UtcNow});await db.SaveChangesAsync(ct);TempData["StatusMessage"]="Tenant administrator created locally.";return RedirectToAction(nameof(Index));}
    [HttpGet] public async Task<IActionResult> Edit(long id,CancellationToken ct){var x=await db.UserExtended.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id&&!x.IsStudent,ct);return x is null?NotFound():View("Form",await Prepare(Map(x),ct));}
    [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Edit(TenantAdminFormViewModel model,CancellationToken ct){await Validate(model,ct,false);if(!ModelState.IsValid)return View("Form",await Prepare(model,ct));var x=await db.UserExtended.SingleOrDefaultAsync(x=>x.Id==model.Id&&!x.IsStudent,ct);if(x is null)return NotFound();if(x.UpdatedOn!=model.UpdatedOn){ModelState.AddModelError("","This record was changed by another user. Reload and try again.");return View("Form",await Prepare(model,ct));}x.TenantId=model.TenantId;x.Name=model.Name.Trim();x.Surname=model.Surname?.Trim();x.Email=model.Email.Trim();x.PhoneNumber=model.PhoneNumber?.Trim();x.UserInternalId=model.UserInternalId?.Trim();x.UserRoleId=model.UserRoleId;x.Address=model.Address?.Trim();x.IsActive=model.IsActive;x.UpdatedBy=UserId();x.UpdatedOn=DateTime.UtcNow;await db.SaveChangesAsync(ct);TempData["StatusMessage"]="Tenant administrator updated.";return RedirectToAction(nameof(Index));}
    [HttpGet] public async Task<IActionResult> Details(long id,CancellationToken ct){var x=await db.UserExtended.AsNoTracking().Include(x=>x.Tenant).SingleOrDefaultAsync(x=>x.Id==id&&!x.IsStudent,ct);return x is null?NotFound():View(x);}
    [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Provision(long id,CancellationToken ct){var x=await db.UserExtended.Include(x=>x.Tenant).SingleOrDefaultAsync(x=>x.Id==id&&!x.IsStudent,ct);if(x is null)return NotFound();if(!x.IsActive||!x.Tenant.IsActive||string.IsNullOrWhiteSpace(x.Email)||x.UserRoleId is null){TempData["ErrorMessage"]="The user must be active and have an active tenant, email, and product role before provisioning.";return RedirectToAction(nameof(Index));}if(!string.IsNullOrWhiteSpace(x.OutSystemsUserId)){TempData["ErrorMessage"]="This administrator is already provisioned.";return RedirectToAction(nameof(Index));}try{var externalId=await provisioning.ProvisionAsync(x,ct);x.OutSystemsUserId=externalId;x.UpdatedBy=UserId();x.UpdatedOn=DateTime.UtcNow;await db.SaveChangesAsync(ct);TempData["StatusMessage"]=$"{x.Name} was provisioned successfully.";}catch(Exception ex){logger.LogError(ex,"Tenant administrator {UserId} provisioning failed",x.Id);TempData["ErrorMessage"]="Provisioning failed. No local provisioning ID was saved; you can retry safely.";}return RedirectToAction(nameof(Index));}
    private async Task Validate(TenantAdminFormViewModel m,CancellationToken ct,bool creating){var tenant=await db.Tenants.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==m.TenantId,ct);if(tenant is null||creating&&!tenant.IsActive)ModelState.AddModelError(nameof(m.TenantId),"Select an active tenant.");var email=m.Email.Trim();if(await db.UserExtended.AnyAsync(x=>x.Id!=m.Id&&x.Email==email,ct))ModelState.AddModelError(nameof(m.Email),"This email is already in use.");}
    private async Task<TenantAdminFormViewModel> Prepare(TenantAdminFormViewModel m,CancellationToken ct){m.Tenants=await db.Tenants.AsNoTracking().Where(x=>x.IsActive||x.Id==m.TenantId).OrderBy(x=>x.Name).Select(x=>new SelectListItem(x.Name,x.Id.ToString())).ToListAsync(ct);return m;}
    private static TenantAdminFormViewModel Map(UserExtended x)=>new(){Id=x.Id,TenantId=x.TenantId,Name=x.Name??"",Surname=x.Surname,Email=x.Email??"",PhoneNumber=x.PhoneNumber,UserInternalId=x.UserInternalId,UserRoleId=x.UserRoleId,Address=x.Address,IsActive=x.IsActive,OutSystemsUserId=x.OutSystemsUserId,UpdatedOn=x.UpdatedOn};
    private long UserId()=>long.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);
}
